package com.sgasubtitler.engine;
import com.sgasubtitler.model.*;import java.io.*;import java.nio.file.*;import java.util.*;
public final class WavExporter {public void export(SgaFile file,Path output)throws IOException{if(file.audioChunks().isEmpty())throw new IOException("Aucun audio A1");int rate=SgaFile.AudioInfo.of(file.audioChunks().getFirst()).rate();var pcm=new ByteArrayOutputStream();for(SgaChunk c:file.audioChunks()){byte[]d=c.data();int end=d.length-(d.length>8&&d[d.length-1]==0?1:0);for(int i=8;i<end;i++){int sample=d[i]&255,sign=sample>>>7,mag=sample&127;pcm.write(sign==1?sample:127-mag);}}byte[]data=pcm.toByteArray();try(var out=new DataOutputStream(Files.newOutputStream(output))){out.writeBytes("RIFF");le32(out,36+data.length);out.writeBytes("WAVEfmt ");le32(out,16);le16(out,1);le16(out,1);le32(out,rate);le32(out,rate);le16(out,1);le16(out,8);out.writeBytes("data");le32(out,data.length);out.write(data);}}private static void le16(DataOutputStream o,int v)throws IOException{o.write(v);o.write(v>>>8);}private static void le32(DataOutputStream o,int v)throws IOException{le16(o,v);le16(o,v>>>16);}}
